// tabcap status (0.7-B, owner decision 2026-10-17): one answer for the state
// that is otherwise spread over `daemon status`, `session list`, `trace
// status`, `plugin list`, `handoff status` and guard output, plus
// `conflicts`: sentences generated by pure rules over that answer, each with
// a `code` and the `next` command. The answer reads the daemon's own objects
// (tabs, recorders, tracers, the guard, the plugin registry); it keeps no
// state of its own. It is read-only and daemon-wide: the daemon answers it
// before the command path (main.ts), so it opens no `cmd` window in any
// recording and is never refused while a session waits.

import { join } from "node:path";
import { cachedNames } from "../protection/live.ts";
import { readConfigWarnings } from "../../shared/config.ts";
import { TabcapError } from "../../shared/envelope.ts";
import { withoutUrlCredentials } from "../../shared/launchargs.ts";
import { isRecord } from "../../shared/json.ts";
import { decodePlugins, pluginsFor } from "../hooks/plugins.ts";
import type { Daemon } from "../state.ts";
import { siteOf } from "../../shared/sites.ts";
import { redactUrl, type LiveCtx } from "./liveredact.ts";

export const STATUS_SCHEMA = "tabcap-status/0";

export type StatusDaemon = { running: true; pid: number; version: string; listener: string; socket: string | null; port?: number; startedAt: number } | { running: false; listener: string };

/**
 * `webdriver`: 0.7.6-A (docs/04 §40); `extraArgs` / `dropArgs`: 0.8.1-A (§42); `warnings`: switches that
 * weaken the browser's isolation and skipped user protection rule files, `protectionLive`: config.json protection.live (review 10-21, §42, §41.1, §41.3);
 * null while no browser runs.
 */
export type StatusBrowser = {
  running: boolean;
  pid: number | null;
  mode: "direct" | "ext" | null;
  tabs: number;
  webdriver: "hidden" | "visible" | null;
  extraArgs: string[] | null;
  dropArgs: string[] | null;
  warnings: string[] | null;
  protectionLive: boolean | null;
};

export type StatusRecording = { bundle: string; since: number; entries: number; decodePlugins: string[] };

export type StatusTrace = { state: "off" | "on" | "paused"; decode: boolean; weakRows: number | null };

export type StatusGuardStop = { site: string; rule: string; since: number; reason: "fetch-stop" | "stop-rule"; by: string; request: string };

export type StatusSession = {
  session: string;
  site: string | null;
  account: string | null;
  /** Unbound sessions: the store site the current tab's URL belongs to, else null. */
  tabSite: string | null;
  tabs: number;
  current: string | null;
  /** 0.7-E: the URL of the current tab (else the session's first tab), null without a tab. */
  url: string | null;
  recording: StatusRecording | null;
  state: "running" | "waiting";
  reason: string | null;
  screenshot: string | null;
  trace: StatusTrace;
  guardStops: StatusGuardStop[];
  /** 0.8-A: protection families identified on the current tab's page (≥ 50, cached per navigation; docs/04 §41.3). */
  protection: string[];
};

/** `url`: the request the guard handed over on (0.7-E). */
export type StatusHandoff = { session: string; reason: string; site: string | null; url: string; since: number; screenshot: string | null };

export type ConflictCode = "waiting-and-fetch-stop" | "decode-plugin-outranks-page" | "unbound-session" | "recording-without-browser" | "trace-without-recording";

export type StatusConflict = { code: ConflictCode; session: string; message: string; next: string };

export type StatusFacts = {
  schema: typeof STATUS_SCHEMA;
  daemon: StatusDaemon;
  browser: StatusBrowser;
  sessions: StatusSession[];
  plugins: { decode: string[]; challenge: string[] };
  handoff: StatusHandoff[];
};

/**
 * `next` (0.7-E): what to do first: for a waiting session `tabcap handoff continue` once the human
 * finished (one clause per waiting session; a stop-rule wait is decided on the response first),
 * else the first conflict's next, else null.
 */
/**
 * Review wave 3 (docs/04 §44): config.json's unknown keys, read on every answer (also without a daemon or a
 * browser); `browser.warnings` stays the browser's own. Owner 2026-10-22: a config.json that cannot be read
 * (not JSON or not an object: `bad-input`; unreadable: `io`) is `error`, with `warnings` empty, and the rest of
 * the answer stays, so a waiting handoff is still seen; `error` is null when the file reads.
 */
export type StatusConfigError = { code: "bad-input" | "io"; message: string; next: string };

export type StatusConfig = { warnings: string[]; error: StatusConfigError | null };

export type StatusAnswer = StatusFacts & { config: StatusConfig; conflicts: StatusConflict[]; next: string | null };

/** The top-level `next` of a status answer (pure). */
export function nextOf(f: StatusFacts, conflicts: readonly StatusConflict[]): string | null {
  const waiting = f.sessions.filter((s) => s.state === "waiting");
  if (waiting.length > 0) return waiting.map((s) => waitingNext(s, f)).join("; ");
  return conflicts[0]?.next ?? null;
}

/**
 * One waiting session's clause of `next`; 0.7.1-A: on a take-over the user is already at the tab, so there is nobody to tell.
 * A stop-rule wait gives the guard's own advice (guard.ts STOP_RULE_NEXT, docs/04 §18 0.6-I, §39): look at the
 * response first, then `handoff continue` or `guard resume --site`; the request and site come from the session's
 * own stop-rule stop (else the handoff's site and an `<r-N>` placeholder).
 */
function waitingNext(s: StatusSession, f: StatusFacts): string {
  const go = `\`tabcap handoff continue ${S(s.session)}\``;
  const shot = s.screenshot === null ? "" : ` (screenshot ${s.screenshot})`;
  if (s.reason === "human-takeover") return `session ${q(s.session)}: the user took over its tab (human-takeover); do not act on the page; when they say they are done: ${go}`;
  if (s.reason === "stop-rule") {
    const own = s.guardStops.find((x) => x.reason === "stop-rule" && x.by === s.session);
    const request = own?.request ?? "<r-N>";
    const site = own?.site ?? f.handoff.find((h) => h.session === s.session)?.site ?? null;
    return `session ${q(s.session)} waits (stop-rule${own === undefined ? "" : ` ${own.rule} fired on ${own.request}`})${shot}: look at the response first (\`tabcap net body ${request} ${S(s.session)}\`); go on only when the human (or you, after judging) decides to: ${go}${site === null ? "" : ` (or \`tabcap guard resume --site ${site}\`)`}`;
  }
  return `session ${q(s.session)} waits for the human (${s.reason ?? "?"}): tell the user${shot}; after they finished in the browser: ${go}`;
}

const q = (s: string) => JSON.stringify(s);
const S = (s: string) => `--session ${s}`;

// ---------------------------------------------------------------- rules (pure)

/**
 * (a) A session waits for the human while fetches on its site are stopped.
 * `guard resume --site` lifts the fetch stop; it ends the wait only when both
 * came from one site stop rule of this session (handoff.ts guardResume).
 * `handoff continue` ends the wait and lifts the stops this session set off.
 */
export function ruleWaitingAndFetchStop(f: StatusFacts): StatusConflict[] {
  const out: StatusConflict[] = [];
  for (const s of f.sessions) {
    if (s.state !== "waiting") continue;
    const stops = s.guardStops.filter((x) => !(x.reason === "stop-rule" && s.reason === "stop-rule" && x.by === s.session));
    if (stops.length === 0) continue;
    const sites = [...new Set(stops.map((x) => x.site))];
    const others = [...new Set(stops.filter((x) => x.by !== s.session).map((x) => x.site))];
    out.push({
      code: "waiting-and-fetch-stop",
      session: s.session,
      message: `session ${q(s.session)} waits for the human (${s.reason ?? "?"}) and fetches on ${sites.join(", ")} are stopped: \`tabcap guard resume\` lifts the fetch stop but does not end the wait`,
      next: `after the human finished in the browser: \`tabcap handoff continue ${S(s.session)}\`${others.length === 0 ? "" : `; the stop another session set off stays until \`tabcap guard resume --site ${others[0] ?? ""}\``}`,
    });
  }
  return out;
}

/**
 * (b) The observe mode (`trace start --decode`) runs while decode plugins
 * apply: a body a plugin filed a view for is not observed and plugin views
 * outrank `by:"page"` views (docs/04 §33 D4). 0.7-E: a recording reads the
 * enabled plugins per body, so the enabled ones are what applies, to the
 * current recording from its next body or to the next recording.
 */
export function ruleDecodePluginOutranksPage(f: StatusFacts): StatusConflict[] {
  const out: StatusConflict[] = [];
  for (const s of f.sessions) {
    if (s.trace.state === "off" || !s.trace.decode) continue;
    const names = f.plugins.decode;
    if (names.length === 0) continue;
    const first = names.length === 1 ? (names[0] ?? "<name>") : "<name>";
    out.push({
      code: "decode-plugin-outranks-page",
      session: s.session,
      message: `session ${q(s.session)} observes the page (trace --decode) while decode plugin(s) ${names.join(", ")} apply${s.recording === null ? " to the next recording" : " to its recording"}: plugin views outrank page views, and a body a plugin decoded is not observed`,
      next: `to observe the page: \`tabcap plugin disable ${first}\`${s.recording === null ? "" : " (applies from the next body; bodies already decoded keep their plugin view)"}`,
    });
  }
  return out;
}

/**
 * (c) A session with tabs, no site binding, and its current tab on a store
 * site (`tabSite`): `fill --secret` is refused there. A session browsing
 * pages of no store site (a plain `default`) is not reported (owner 10-17).
 */
export function ruleUnboundSession(f: StatusFacts): StatusConflict[] {
  return f.sessions.flatMap((s) => {
    if (s.tabs === 0 || s.site !== null || s.tabSite === null) return [];
    return [
      {
        code: "unbound-session" as const,
        session: s.session,
        message: `session ${q(s.session)} is on store site ${s.tabSite} but not bound to it: \`fill --secret\` will be refused`,
        next: `if it needs a stored secret: \`tabcap session stop ${s.session}\`, then \`tabcap session start ${s.session} --site ${s.tabSite}\``,
      },
    ];
  });
}

/** (d) A recording is still open on a session that has no open tab (the browser or its tabs are gone). */
export function ruleRecordingWithoutBrowser(f: StatusFacts): StatusConflict[] {
  return f.sessions.flatMap((s) => {
    if (s.recording === null || (f.browser.running && s.tabs > 0)) return [];
    return [
      {
        code: "recording-without-browser" as const,
        session: s.session,
        message: `session ${q(s.session)} still records into ${s.recording.bundle} but ${f.browser.running ? "has no open tab" : "the browser is not running"}: nothing more reaches the bundle`,
        next: `\`tabcap net stop ${S(s.session)}\` finishes the bundle${f.browser.running ? `; or \`tabcap navigate <url> ${S(s.session)}\` to go on recording` : ""}`,
      },
    ];
  });
}

/** (e) Trace mode is on in a session that is not recording. */
export function ruleTraceWithoutRecording(f: StatusFacts): StatusConflict[] {
  return f.sessions
    .filter((s) => s.trace.state !== "off" && s.recording === null)
    .map((s) => ({
      code: "trace-without-recording" as const,
      session: s.session,
      message: `session ${q(s.session)} traces${s.trace.decode ? " (observe mode)" : ""} but is not recording: ${s.trace.decode ? "observe" : "signal"} rows reach no bundle until \`tabcap net start\``,
      next: `\`tabcap net start ${S(s.session)}\`, then load the page again`,
    }));
}

export const CONFLICT_RULES: ReadonlyArray<(f: StatusFacts) => StatusConflict[]> = [ruleWaitingAndFetchStop, ruleDecodePluginOutranksPage, ruleUnboundSession, ruleRecordingWithoutBrowser, ruleTraceWithoutRecording];

/** Every rule over the facts, in rule order. */
export function conflictsOf(f: StatusFacts): StatusConflict[] {
  return CONFLICT_RULES.flatMap((r) => r(f));
}

// ---------------------------------------------------------------- reading the daemon

export function enabledPlugins(configDir: string): { decode: string[]; challenge: string[] } {
  return { decode: decodePlugins(configDir).map((p) => p.name), challenge: pluginsFor(configDir, "challenge").map((p) => p.name) };
}

function tabSiteOf(d: Daemon, url: string | null): string | null {
  if (d.store === null || url === null) return null;
  let u: URL;
  try {
    u = new URL(url);
  } catch {
    return null;
  }
  if (u.protocol !== "http:" && u.protocol !== "https:") return null;
  return siteOf(d.store.listSites(), null, u).site;
}

/** The status answer from the daemon's objects; `daemon` is the process part main.ts knows. */
export function statusOf(d: Daemon, daemon: StatusDaemon): StatusAnswer {
  const b = d.browser;
  const names: string[] = [];
  const add = (n: string) => {
    if (!names.includes(n)) names.push(n);
  };
  if (b !== null) for (const n of b.tabs.sessions.keys()) add(n);
  const extra = new Set<string>([...d.recorders.keys(), ...d.tracers.keys(), ...d.sites.keys(), ...d.guard.all().filter((h) => h.state === "waiting").map((h) => h.session), ...d.guard.allFetchStops().map((s) => s.session)]);
  for (const n of [...extra].sort()) add(n);
  const stops = d.guard.allFetchStops();
  // docs/04 §8.3: URLs shown with sensitive query parameters redacted (status has no --reveal)
  const c: LiveCtx = { scrub: (s) => d.secrets.scrub(s) };
  const sessions: StatusSession[] = names.map((name) => {
    const bound = d.sites.get(name) ?? null;
    const tabs = b === null ? [] : b.tabs.sessionTabs(name);
    const current = b?.tabs.session(name)?.current ?? null;
    const currentTab = tabs.find((t) => t.id === current) ?? tabs[0];
    const currentUrl = currentTab?.url ?? null;
    const r = d.recorders.get(name);
    const tr = d.tracers.get(name);
    const h = d.guard.get(name);
    const waiting = h !== null && h.state === "waiting";
    const site = bound?.site ?? null;
    const hostSite = site ?? tabSiteOf(d, currentUrl);
    return {
      session: name,
      site,
      account: bound?.account ?? null,
      tabSite: site === null ? tabSiteOf(d, currentUrl) : null,
      tabs: tabs.length,
      current,
      url: currentUrl === null ? null : redactUrl(currentUrl, c),
      recording: r === undefined ? null : { bundle: r.dir, since: recordingSince(r.status()), entries: r.index.length, decodePlugins: r.decodePlugins },
      state: waiting ? "waiting" : "running",
      reason: waiting ? h.reason : null,
      screenshot: waiting ? h.screenshot : null,
      trace: tr === undefined || tr.stoppedNow ? { state: "off", decode: false, weakRows: null } : { state: tr.paused ? "paused" : "on", decode: tr.observing, weakRows: tr.observing ? tr.weakRowCount : null },
      guardStops: stops
        .filter((s) => s.session === name || (hostSite !== null && s.site === hostSite) || (waiting && h.site !== null && s.site === h.site))
        .map((s) => ({ site: s.site, rule: s.rule, since: s.since, reason: s.reason, by: s.session, request: s.request })),
      protection: cachedNames(currentTab),
    };
  });
  const facts: StatusFacts = {
    schema: STATUS_SCHEMA,
    daemon,
    browser:
      b === null
        ? { running: false, pid: null, mode: null, tabs: 0, webdriver: null, extraArgs: null, dropArgs: null, warnings: null, protectionLive: null }
        : {
            running: true,
            pid: b.info.pid,
            mode: b.t.kind,
            tabs: [...b.tabs.tabs.values()].filter((x) => !x.closed).length,
            webdriver: b.info.webdriver,
            // Review wave 3: URL values without their userinfo, as browser start / browser status show them (§42).
            extraArgs: withoutUrlCredentials(b.info.extraArgs),
            dropArgs: withoutUrlCredentials(b.info.dropArgs),
            warnings: b.info.warnings,
            protectionLive: b.info.protectionLive,
          },
    sessions,
    plugins: enabledPlugins(d.paths.config),
    handoff: d.guard
      .all()
      .filter((h) => h.state === "waiting")
      .map((h) => ({ session: h.session, reason: h.reason, site: h.site, url: redactUrl(h.url, c), since: h.since, screenshot: h.screenshot })),
  };
  const config = statusConfig(d.paths.configFile);
  const conflicts = conflictsOf(facts);
  return { ...facts, config, conflicts, next: nextOf(facts, conflicts) };
}

/** `config` of a status answer: the file's warnings, or the error `readConfigRaw` gives for it (`bad-input` / `io`); any other error propagates. */
export function statusConfig(file: string): StatusConfig {
  try {
    return { warnings: readConfigWarnings(file), error: null };
  } catch (e) {
    if (e instanceof TabcapError && (e.code === "bad-input" || e.code === "io")) return { warnings: [], error: { code: e.code, message: e.message, next: e.next } };
    throw e;
  }
}

function recordingSince(st: Record<string, unknown>): number {
  const v = st["since"];
  return typeof v === "number" ? v : 0;
}

/** `tabcap status` when no daemon answers: the CLI still reports what it can read itself (plugins). */
export function offlineStatus(configDir: string, listener: string): StatusAnswer {
  const config = statusConfig(join(configDir, "config.json"));
  const facts: StatusFacts = {
    schema: STATUS_SCHEMA,
    daemon: { running: false, listener },
    browser: { running: false, pid: null, mode: null, tabs: 0, webdriver: null, extraArgs: null, dropArgs: null, warnings: null, protectionLive: null },
    sessions: [],
    plugins: enabledPlugins(configDir),
    handoff: [],
  };
  const conflicts = conflictsOf(facts);
  return { ...facts, config, conflicts, next: nextOf(facts, conflicts) };
}

// ---------------------------------------------------------------- --text

const recs = (v: unknown): Record<string, unknown>[] => (Array.isArray(v) ? v.filter(isRecord) : []);
const strs = (v: unknown): string[] => (Array.isArray(v) ? v.filter((x): x is string => typeof x === "string") : []);
const rec = (v: unknown): Record<string, unknown> => (isRecord(v) ? v : {});
const txt = (v: unknown): string => (typeof v === "string" ? v : typeof v === "number" || typeof v === "boolean" ? String(v) : "?");

/** `tabcap status --text`: one screen — the daemon line, one line per session, then the conflicts. Reads the JSON defensively (it comes over the wire). */
/** 0.8.1-A: `, chrome args +N -M` when the browser runs with custom args (docs/04 §42). */
function chromeArgsText(br: Record<string, unknown>): string {
  const n = (v: unknown): number => (Array.isArray(v) ? v.length : 0);
  const add = n(br["extraArgs"]);
  const drop = n(br["dropArgs"]);
  return add + drop === 0 ? "" : `, chrome args +${add} -${drop}`;
}

export function renderStatusText(data: unknown): string {
  const s = rec(data);
  const dmn = rec(s["daemon"]);
  const br = rec(s["browser"]);
  const pl = rec(s["plugins"]);
  const plugins = [...strs(pl["decode"]).map((n) => `decode ${n}`), ...strs(pl["challenge"]).map((n) => `challenge ${n}`)];
  const head =
    dmn["running"] === true
      ? `daemon pid ${txt(dmn["pid"])} (${txt(dmn["listener"])}) · ${br["running"] === true ? `browser pid ${txt(br["pid"])} ${txt(br["mode"])}, ${txt(br["tabs"])} tab(s), webdriver ${txt(br["webdriver"])}${chromeArgsText(br)}` : "browser not running"}`
      : "daemon not running (`tabcap daemon start`)";
  const lines = [`tabcap status · ${head} · plugins: ${plugins.length === 0 ? "none" : plugins.join(", ")}`];
  // Review wave 3: config.json's unknown keys, one line each, under the head line; owner 2026-10-22: a
  // config.json that cannot be read is one `config error:` line and its `  next:` line in that place.
  const cfg = rec(s["config"]);
  const cfgError = isRecord(cfg["error"]) ? cfg["error"] : null;
  if (cfgError !== null) lines.push(`config error: ${txt(cfgError["message"])}`, `  next: ${txt(cfgError["next"])}`);
  for (const w of strs(cfg["warnings"])) lines.push(`warning: ${w}`);
  const sessions = recs(s["sessions"]);
  if (sessions.length === 0) lines.push("(no sessions)");
  for (const x of sessions) {
    const site = typeof x["site"] === "string" ? `site ${x["site"]}${typeof x["account"] === "string" ? ` (${x["account"]})` : ""}` : "no site";
    const r = isRecord(x["recording"]) ? x["recording"] : null;
    const tr = rec(x["trace"]);
    const trace = tr["state"] === "off" || tr["state"] === undefined ? "trace off" : `trace ${txt(tr["state"])}${tr["decode"] === true ? ` decode (weak ${txt(tr["weakRows"])})` : ""}`;
    const state = x["state"] === "waiting" ? `WAITING ${txt(x["reason"])}${typeof x["url"] === "string" ? ` at ${x["url"]}` : ""}${typeof x["screenshot"] === "string" ? ` (screenshot ${x["screenshot"]})` : ""}` : "running";
    const stops = recs(x["guardStops"]).map((g) => `${txt(g["site"])} ${txt(g["rule"])}`);
    const parts = [
      site,
      `${txt(x["tabs"])} tab(s)${typeof x["current"] === "string" ? ` (current ${x["current"]})` : ""}`,
      r === null ? "not recording" : `recording ${txt(r["entries"])} req → ${txt(r["bundle"])}`,
      state,
      trace,
      ...(stops.length === 0 ? [] : [`fetch stopped: ${stops.join(", ")}`]),
      ...(strs(x["protection"]).length === 0 ? [] : [`protection ${strs(x["protection"]).join(", ")}`]),
    ];
    lines.push(`${txt(x["session"])}: ${parts.join(" · ")}`);
  }
  const conflicts = recs(s["conflicts"]);
  lines.push(conflicts.length === 0 ? "conflicts: none" : `conflicts (${conflicts.length}):`);
  for (const c of conflicts) {
    lines.push(`- [${txt(c["code"])}] ${txt(c["message"])}`);
    lines.push(`  next: ${txt(c["next"])}`);
  }
  if (typeof s["next"] === "string") lines.push(`next: ${s["next"]}`);
  return lines.join("\n");
}
